command:
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { dispatch } from './src/dispatch.js';
import { registry } from './src/registry.js';
import { handle as mail } from './src/channels/mail.js';
import { handle as audit } from './src/channels/audit.js';
import { handle as legacy } from './src/channels/legacy.js';

assert.deepEqual(Object.keys(registry).sort(), ['audit', 'mail']);
assert.equal(registry.mail, mail);
assert.equal(registry.audit, audit);
assert.equal(Object.values(registry).includes(legacy), false);
assert.equal(dispatch({ kind: 'mail', payload: ' Hi ' }), 'mail:hi');
assert.equal(dispatch({ kind: 'audit', payload: ' Hi ' }), 'audit:" Hi "');
assert.throws(() => dispatch({ kind: 'unknown', payload: ' Hi ' }), { message: 'unknown kind' });
const answer = {
  registered_files: ['src/channels/audit.js', 'src/channels/mail.js'],
  selected_file: 'src/channels/mail.js',
  selected_output: 'mail:hi',
  unknown_kind_error: 'unknown kind',
  target_depends_on_runtime_kind: true,
  legacy_reachable_from_dispatch: false
};
writeFileSync('answer.json', `${JSON.stringify(answer, null, 2)}\n`);
assert.deepEqual(JSON.parse(readFileSync('answer.json', 'utf8')), answer);
console.log('Verified registry mappings, mail and audit dispatch, unknown-kind error, legacy exclusion, and answer.json.');
NODE

